// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // c.supportsInterface(interfaceId) should never return false when either condition is true
        // But the bug requires both, so there exists an interfaceId where reference returns true, mutant returns false
        vm.assume(interfaceId != type(IAccessControl).interfaceId);
        bool refResult = c.supportsInterface(interfaceId);
        // The reference should return true if super.supportsInterface returns true
        // The mutant returns false because it requires both to be true and interfaceId != IAccessControl
        // So the property: if super.supportsInterface(interfaceId) would return true, c.supportsInterface must return true.
        // But we can only observe c's public surfaces.
        // Instead, we assert that for any interfaceId, if it equals type(IERC165).interfaceId,
        // c.supportsInterface must return true.
        // In the reference, super.supportsInterface(type(IERC165).interfaceId) returns true, so overall true.
        // In the mutant, requires both, so false.
        if (interfaceId == type(IERC165).interfaceId) {
            assertTrue(refResult);
        }
    }
}

