import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        vm.assume(interfaceId != type(IAccessControl).interfaceId);
        bool okOriginal = true;
        try c.supportsInterface(interfaceId) returns (bool res) { okOriginal = res; } catch { okOriginal = false; }
        bool okBuggy = false;
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x01ffc9a700000000000000000000000000000000000000000000000000000000)
            mstore(add(ptr, 4), interfaceId)
            let success := call(gas(), c, 0, ptr, 0x24, ptr, 0x20)
            okBuggy := and(success, eq(mload(ptr), 0x01))
        }
        assertTrue(!okBuggy || okOriginal);
    }
}

