pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // 1. We need another address to test against; deployer is already given a role.
        //    Account must not be address(0) to show the difference.
        vm.assume(account != address(0));
        // 2. Ensure the deployer (this test contract) has the role, and account does not.
        //    Deployer already has TIMELOCK_ADMIN_ROLE from the constructor.
        //    We can use any bytes32 role; the constructor sets TIMELOCK_ADMIN_ROLE for the deployer.
        bool expectedForAccount = !c.hasRole(role, account);
        bool actualForAccount = c.hasRole(role, account);
        // 3. The rule: hasRole(role, account) must return the same result for a specific account,
        //    not the membership of address(0). Since the deployer has the role and account does not,
        //    hasRole(role, account) should be false. In the buggy version, it returns _roles[role].members[address(0)],
        //    which is true if deployer (or any entity with address(0) role) has the role.
        //    We check: the returned value must match the expected false for a non-member account.
        assertTrue(actualForAccount == expectedForAccount);
    }
}

